export function parseInvoiceText(rawText, options = {}) {
  const text = String(rawText || "").replace(/\r/g, "");
  const lines = text
    .split("\n")
    .map((l) => l.replace(/\u00a0/g, " ").replace(/[ \t]+/g, " ").trimEnd());

  const nonEmpty = lines.filter((l) => l.trim().length > 0);
